  "The user holds a privileged role (for example Owner, Editor or Discovery Engine Admin) that implicitly grants access. Reduce the privileged role before applying per-user enforcement.": "사용자가 액세스를 암묵적으로 부여하는 특권 역할(예: 소유자, 편집자, Discovery Engine 관리자)을 보유하고 있습니다. 사용자 단위 통제를 적용하기 전에 특권 역할을 축소하십시오.",
  "Another role grants Antigravity access. Remove it, or add it to the managed access roles in Settings > Governance policy.": "다른 역할이 Antigravity 액세스를 부여하고 있습니다. 해당 역할을 제거하거나 설정 > 거버넌스 정책의 관리 대상 액세스 역할에 추가하십시오.",
  "Access is granted through a Google Group or domain binding. Remove the user from the group, or replace the group binding with individual user bindings.": "Google 그룹 또는 도메인 바인딩을 통해 액세스가 부여되어 있습니다. 그룹에서 사용자를 제외하거나 그룹 바인딩을 개별 사용자 바인딩으로 교체하십시오.",
  "Access is inherited from a folder or organization IAM policy. Adjust the ancestor policy to enforce limits for this user.": "폴더 또는 조직 IAM 정책에서 액세스가 상속되고 있습니다. 이 사용자를 제한하려면 상위 정책을 조정하십시오.",
  "The user has both the access role and a marker role, or conditional bindings. Resolve the conflicting bindings manually.": "사용자가 액세스 역할과 마커 역할을 동시에 보유하거나 조건부 바인딩이 있습니다. 충돌하는 바인딩을 수동으로 정리하십시오.",
  "The project IAM policy could not be read. Grant the control plane identity resourcemanager.projects.getIamPolicy.": "프로젝트 IAM 정책을 읽을 수 없습니다. 컨트롤 플레인 ID에 resourcemanager.projects.getIamPolicy 권한을 부여하십시오.",
  "Folder or organization policies could not be verified. Grant the control plane identity read access to ancestor IAM policies.": "폴더 또는 조직 정책을 확인할 수 없습니다. 컨트롤 플레인 ID에 상위 IAM 정책 읽기 권한을 부여하십시오.",
  "Monitor per-user Antigravity usage and enforce token and request caps through project IAM, with safety gates that prevent unsafe bulk changes.": "사용자별 Antigravity 사용량을 모니터링하고 프로젝트 IAM으로 토큰 및 요청 한도를 집행합니다. 안전 게이트가 위험한 일괄 변경을 방지합니다.",
