  "Counted only when Antigravity for organizations writes businessaicode.googleapis.com/inference_response logs in a scanned project. Antigravity used with a personal account writes no such log.": "Antigravity for organizations가 스캔 대상 프로젝트에 businessaicode.googleapis.com/inference_response 로그를 남길 때만 집계됩니다. 개인 계정으로 쓰는 Antigravity는 이 로그를 남기지 않습니다.",
  "Metadata logging is off in an active location": "활성 위치 중 일부에 메타데이터 로깅이 꺼져 있습니다",
