  "No need to add these. Select a page to open it.": "따로 추가할 필요가 없습니다. 화면 이름을 누르면 해당 화면으로 이동합니다.",
  "Looking for something that is not listed?": "찾는 데이터가 목록에 없나요?",
  "New logs appear here automatically within about 10 minutes after a product starts writing to Cloud Logging.": "제품이 Cloud Logging에 로그를 쓰기 시작하면 약 10분 안에 이 목록에 자동으로 나타납니다.",
  "Log dashboards read Cloud Logging directly, so they cover its retention period (30 days by default) and count at most {n} entries per view. To keep longer history or count everything, export the log to BigQuery; the exported table then appears in this list.": "로그 대시보드는 Cloud Logging을 직접 읽으므로 보존 기간(기본 30일) 안의 데이터만 보이고 한 번에 최대 {n}건까지 집계합니다. 더 오래 보관하거나 전체를 집계하려면 로그를 BigQuery로 내보내십시오. 내보낸 테이블도 이 목록에 나타납니다.",
  "To chart only part of a log, use Custom setup. To list the tables of another BigQuery dataset, add it under Settings > Workspace and data sources > Additional telemetry datasets.": "로그의 일부만 보려면 '직접 설정'을 사용하십시오. 다른 BigQuery 데이터셋의 테이블을 목록에 넣으려면 설정 > 워크스페이스 및 데이터 소스 > 추가 텔레메트리 데이터셋에 추가하십시오.",
