  "How it works": "작동 방식",
  "1. The selected Gemini model writes BigQuery SQL using the live schema of your audit, billing and connector tables.": "1. 선택한 Gemini 모델이 감사, 결제, 커넥터 테이블의 실시간 스키마를 바탕으로 BigQuery SQL을 작성합니다.",
  "2. The query is validated: single read-only statement, allowlisted datasets only, byte-billing cap enforced.": "2. 쿼리를 검증합니다. 단일 읽기 전용 문장, 허용된 데이터셋만 조회, 처리 바이트 상한을 적용합니다.",
  "3. Results are summarized from the returned rows only. Inspect the SQL under every answer.": "3. 반환된 행만으로 결과를 요약합니다. 모든 답변 아래에서 SQL을 확인할 수 있습니다.",
  "Ask your governance data anything": "거버넌스 데이터에 무엇이든 질문하십시오",
  "Usage by model, spend by service, Model Armor blocks, agent activity, licenses and more. Choose a suggestion or type a question.": "모델별 사용량, 서비스별 비용, Model Armor 차단, 에이전트 활동, 라이선스 등을 질문할 수 있습니다. 추천 질문을 선택하거나 직접 입력하십시오.",
