  "Query results can include free text, such as prompts, that the dashboards hide from viewers. Off by default.": "쿼리 결과에는 대시보드가 뷰어에게 숨기는 프롬프트 같은 원문이 포함될 수 있습니다. 기본값은 꺼짐입니다.",
  "The AI Analyst is available to administrators. An administrator can allow viewers in Settings > Governance policy > AI Analyst limits.": "AI 애널리스트는 관리자만 사용할 수 있습니다. 관리자가 설정 > 거버넌스 정책 > AI 애널리스트 제한에서 뷰어 사용을 허용할 수 있습니다.",
