  "The control plane reads data in place from your Google Cloud project. It does not copy logs or billing data to any external system.": "컨트롤 플레인은 Google Cloud 프로젝트의 데이터를 그 자리에서 읽으며, 로그나 결제 데이터를 외부 시스템으로 복사하지 않습니다.",
  "All queries run with the deployment service account and are restricted to read-only access, except explicitly confirmed governance actions on project IAM.": "모든 쿼리는 배포 서비스 계정으로 실행되며, 명시적으로 확인한 프로젝트 IAM 거버넌스 조치를 제외하고 읽기 전용으로 제한됩니다.",
  "Administrative actions are written to Cloud Logging (agy-admin admin_actions) for audit.": "관리 조치는 감사를 위해 Cloud Logging(agy-admin admin_actions)에 기록됩니다.",
