  "No inference log records in the window; automatic restores are withheld.": "평가 윈도우에 추론 로그가 없어 자동 복구를 보류합니다.",
  "{a} of {b} users have a determinate state.": "사용자 {b}명 중 {a}명의 상태를 판별했습니다.",
  "{a} inference log records in the window.": "평가 윈도우의 추론 로그 {a}건",
  "No group or domain grants on {a}.": "{a}에 그룹 또는 도메인 부여가 없습니다.",
  "{a} group or domain grant(s) on {b}; affected users are not enforceable.": "{b}에 그룹 또는 도메인 부여가 {a}건 있어 해당 사용자는 통제할 수 없습니다.",
  "Dry run: no IAM change was made.": "시뮬레이션: IAM은 변경되지 않았습니다.",
  "Aborted by safety gates: no IAM change was made.": "안전 게이트에 의해 중단되어 IAM은 변경되지 않았습니다.",
  "The user state changed; no IAM change was made.": "사용자 상태가 바뀌어 IAM을 변경하지 않았습니다.",
  "IAM policy updated.": "IAM 정책을 갱신했습니다.",
  "The role exists in a deleted state; undelete it in IAM.": "역할이 삭제된 상태로 남아 있습니다. IAM에서 삭제를 취소하십시오.",
  "The role already exists.": "역할이 이미 있습니다.",
  "The role could not be created.": "역할을 만들 수 없습니다.",
  "Marker role {a} does not exist. Run setup first.": "마커 역할 {a}이(가) 없습니다. Antigravity 통제 화면의 '집행 사전 요구 사항'에서 '마커 역할 생성'을 먼저 실행하십시오.",
  "Role {a} is needed to stop Antigravity for a person, but the dashboard service account is not allowed to read or create custom roles in this project. Grant it roles/iam.roleAdmin and try again.": "Antigravity를 막으려면 역할 {a}이(가) 필요한데, 대시보드 서비스 계정에 이 프로젝트의 커스텀 역할을 읽거나 만들 권한이 없습니다. 서비스 계정에 roles/iam.roleAdmin을 부여한 뒤 다시 시도하십시오.",
  "Role {a} is needed to stop Antigravity for a person, but it is deleted and could not be restored ({b}). Restore it in IAM > Roles, or enter another role ID in Settings > Governance policy.": "Antigravity를 막으려면 역할 {a}이(가) 필요한데, 이 역할이 삭제된 상태이고 복구하지 못했습니다({b}). IAM > 역할에서 복구하거나 설정 > 거버넌스 정책에서 다른 역할 ID를 입력하십시오.",
  "Role {a} is needed to stop Antigravity for a person, but Google Cloud does not accept this role ID right now, which happens for up to 44 days after a role with the same ID was deleted. Enter another role ID in Settings > Governance policy.": "Antigravity를 막으려면 역할 {a}이(가) 필요한데, Google Cloud가 지금은 이 역할 ID를 받아들이지 않습니다. 같은 ID의 역할을 삭제한 뒤 최대 44일 동안 그럴 수 있습니다. 설정 > 거버넌스 정책에서 다른 역할 ID를 입력하십시오.",
  "Role {a} is needed to stop Antigravity for a person, but it could not be created because the permissions of {b} could not be read.": "Antigravity를 막으려면 역할 {a}이(가) 필요한데, {b}의 권한 목록을 읽을 수 없어 역할을 만들지 못했습니다.",
  "Role {a} is needed to stop Antigravity for a person, but it could not be prepared ({b}). Try again in a moment.": "Antigravity를 막으려면 역할 {a}이(가) 필요한데, 역할을 준비하지 못했습니다({b}). 잠시 후 다시 시도하십시오.",
  "The deleted role was restored.": "삭제된 역할을 복구했습니다.",
  "The deleted role could not be restored ({a}).": "삭제된 역할을 복구하지 못했습니다({a}).",
