  "Connector not found.": "커넥터를 찾을 수 없습니다.",
  "Field 'bigquery' must contain project, dataset and table.": "BigQuery 소스에는 프로젝트, 데이터셋, 테이블이 모두 필요합니다.",
  "Field 'bigquery' must contain a valid project, dataset and table.": "BigQuery 소스의 프로젝트, 데이터셋, 테이블 이름이 올바르지 않습니다.",
