  "Malformed response": "서버 응답 형식이 올바르지 않습니다.",
  "The request is invalid.": "요청이 올바르지 않습니다.",
  "The request conflicts with the current state. Reload and try again.": "현재 상태와 충돌하는 요청입니다. 새로 고친 뒤 다시 시도하십시오.",
  "Unknown settings key: {a}": "알 수 없는 설정 키입니다: {a}",
  "Setting {a} cannot be reset from the UI.": "{a} 설정은 화면에서 초기화할 수 없습니다.",
  "{a} can only be changed in config.yaml or the environment.": "{a}은(는) config.yaml 또는 환경 변수에서만 변경할 수 있습니다.",
