  "Field 'question' must be 1 to {a} characters.": "질문은 1~{a}자여야 합니다.",
  "Mapping '{a}' must be a dotted path of identifiers.": "'{a}' 매핑은 점으로 구분된 식별자 경로여야 합니다.",
  "Mapping '{a}' refers to a column that does not exist.": "'{a}' 매핑이 존재하지 않는 열을 가리킵니다.",
  "The user holds a privileged role (for example owner, editor or Discovery Engine admin) that grants access independently of individual bindings. Remove or reduce the privileged role, then re-evaluate the user.": "사용자가 개별 바인딩과 관계없이 액세스를 부여하는 특권 역할(예: owner, editor, Discovery Engine admin)을 보유하고 있습니다. 특권 역할을 제거하거나 축소한 뒤 사용자를 다시 평가하십시오.",
  "Access is granted through an additional access role configured in the governance settings. Remove that role binding before using per-user controls.": "거버넌스 설정에 구성된 추가 액세스 역할을 통해 액세스가 부여되어 있습니다. 사용자별 통제를 사용하기 전에 해당 역할 바인딩을 제거하십시오.",
  "Access is granted through a Google Group or domain binding on the access role. Remove the user from the group, or replace the group grant with individual user bindings.": "액세스 역할에 대한 Google 그룹 또는 도메인 바인딩을 통해 액세스가 부여되어 있습니다. 사용자를 그룹에서 제외하거나 그룹 부여를 개별 사용자 바인딩으로 바꾸십시오.",
  "Access is inherited from a folder or organization IAM policy. Remove the inherited binding at the ancestor level.": "폴더 또는 조직 IAM 정책에서 액세스가 상속되었습니다. 상위 수준에서 상속된 바인딩을 제거하십시오.",
  "The user has a conditional binding, or holds both the access role and a marker role. Resolve the bindings manually so that exactly one unconditional binding remains.": "사용자에게 조건부 바인딩이 있거나 액세스 역할과 마커 역할을 함께 보유하고 있습니다. 조건 없는 바인딩이 하나만 남도록 수동으로 정리하십시오.",
  "The project IAM policy could not be read. Grant resourcemanager.projects.getIamPolicy to the service identity and retry.": "프로젝트 IAM 정책을 읽을 수 없습니다. 서비스 ID에 resourcemanager.projects.getIamPolicy 권한을 부여한 뒤 다시 시도하십시오.",
  "Folder or organization IAM policies could not be read, so inherited access cannot be ruled out. Grant read access to the ancestor policies or review them manually.": "폴더 또는 조직 IAM 정책을 읽을 수 없어 상속된 액세스를 배제할 수 없습니다. 상위 정책 읽기 권한을 부여하거나 수동으로 검토하십시오.",
  "Parameter '{a}' must be a date in YYYY-MM-DD format.": "'{a}' 매개변수는 YYYY-MM-DD 형식의 날짜여야 합니다.",
