  "Usage by product": "제품별 사용량",
  "Products that re-bill model usage under their own billing SKUs, detected automatically. Their tokens are already counted under the underlying models.": "모델 사용량을 자체 결제 SKU로 다시 청구하는 제품을 자동으로 감지합니다. 토큰은 기반 모델 집계에 이미 포함되어 있습니다.",
