  "Only these Google accounts can sign in. Administrators can change settings and run governance actions; viewers have read-only access.": "아래 Google 계정만 로그인할 수 있습니다. 관리자는 설정 변경과 거버넌스 작업을 할 수 있고, 뷰어는 조회만 할 수 있습니다.",
