  "Enter a Google account email, or *@domain to approve every account in that domain.": "Google 계정 이메일을 입력하십시오. *@도메인 형식으로 입력하면 해당 도메인의 모든 계정이 승인됩니다.",
  "Enter a valid email address or a *@domain pattern.": "올바른 이메일 주소 또는 *@도메인 형식을 입력하십시오.",
