  "Gemini Enterprise ran this by itself (session summaries, scheduled runs). It is not a prompt typed by a person.": "Gemini Enterprise가 스스로 실행한 작업(세션 요약, 예약 실행)입니다. 사람이 입력한 프롬프트가 아닙니다.",
  "Model Armor does not record users, and this operation could not be matched to Gemini Enterprise activity.": "Model Armor 로그에는 사용자 정보가 없고, 이 작업은 Gemini Enterprise 활동 로그와도 연결되지 않았습니다.",
