  "Blocked: automatic runs": "차단: 자동 실행",
  "Blocks in runs Gemini Enterprise starts by itself (session summaries, scheduled runs), mostly web search results it screened.": "Gemini Enterprise가 스스로 시작한 실행(세션 요약, 예약 실행)에서 차단된 건수입니다. 대부분 검사된 웹 검색 결과입니다.",
  "{n} of {total} blocks came from automatic runs": "차단 {total}건 중 {n}건은 자동 실행에서 발생했습니다",
  "Gemini Enterprise summarizes sessions and runs scheduled tasks by itself. The web search results these runs read are screened too, so blocks can appear on days nobody used the assistant. They are not prompts typed by people.": "Gemini Enterprise는 세션 요약과 예약 작업을 스스로 실행합니다. 이때 읽어 오는 웹 검색 결과도 검사되므로 아무도 어시스턴트를 쓰지 않은 날에도 차단이 생길 수 있습니다. 사람이 입력한 프롬프트가 아닙니다.",
  "Prompts sent by people only; automatic runs are excluded": "사람이 보낸 프롬프트만 집계하며 자동 실행은 제외합니다",
