  "The Gemini model that writes the query and the answer. Cost spike analysis uses the same model.": "쿼리와 답변을 만드는 Gemini 모델입니다. 비용 급증 분석에도 같은 모델이 사용됩니다.",
  "No Antigravity token usage logs in this project": "이 프로젝트에는 Antigravity 토큰 사용 로그가 없습니다",
  "Token usage appears here when Antigravity for organizations writes its inference log ({log}) to this project.": "조직용 Antigravity가 이 프로젝트에 추론 로그({log})를 남기면 토큰 사용량이 여기에 표시됩니다.",
