  "Run enforcement now": "지금 집행 실행",
  "Per-user caps on tokens, requests and estimated cost within a settlement period. Users over their cap are suspended through project IAM until the period resets, automatically or after administrator review, with exception rules for specific users.": "정산 기간 동안 사용자별 토큰, 요청, 예상 비용 한도를 적용합니다. 한도를 넘은 사용자는 프로젝트 IAM을 통해 기간이 초기화될 때까지 정지되며, 자동 또는 관리자 검토 후 처리됩니다. 특정 사용자에게는 예외 규칙을 둘 수 있습니다.",
  "A safety gate failed. Resolve it before running enforcement.": "안전 게이트가 실패했습니다. 해결한 후 집행을 실행하십시오.",
