  "No expiry": "만료 없음",
  "Usage telemetry is degraded (gate G3), so users capped earlier will not be restored automatically in this cycle. Suspensions whose settlement period has ended are still restored.": "사용량 텔레메트리가 불안정하여(게이트 G3) 이전에 한도로 정지된 사용자는 이번 주기에 자동으로 복원되지 않습니다. 정산 기간이 끝난 정지는 그대로 복원됩니다.",
  "Exception rules are not stored durably": "예외 규칙이 영구 저장되지 않습니다",
  "No enforcement schedule": "집행 일정 없음",
  "Widget layouts can be saved only by a signed-in person.": "위젯 배치는 로그인한 사람만 저장할 수 있습니다.",
  "{n} users are suspended, but no enforcement schedule is configured. Their access returns only when an enforcement run happens after the settlement period resets. Select Run enforcement now after each reset, or set ENFORCEMENT_SCHEDULE and redeploy.": "사용자 {n}명이 정지되어 있지만 집행 일정이 구성되지 않았습니다. 정산 기간이 초기화된 뒤 집행이 실행되어야 접근이 복원됩니다. 초기화될 때마다 '지금 집행 실행'을 누르거나, ENFORCEMENT_SCHEDULE을 설정하고 다시 배포하십시오.",
  "Settings are kept in memory on this deployment, so exception rules and suspension records are lost when the service restarts. Configure a settings bucket (SETTINGS_BUCKET).": "이 배포는 설정을 메모리에만 보관하므로 서비스가 다시 시작되면 예외 규칙과 정지 기록이 사라집니다. 설정 버킷(SETTINGS_BUCKET)을 구성하십시오.",
  "Users in period": "기간 내 사용자",
