  "Enforcement runs, review decisions, exception rules and allow or disallow actions are recorded here.": "집행 실행, 검토 결정, 예외 규칙, 허용/차단 작업이 여기에 기록됩니다.",
  "{b} suspended · {r} restored · {d} blocked by rules · {q} awaiting review": "정지 {b} · 복원 {r} · 규칙 차단 {d} · 검토 대기 {q}",
  "Manual review": "수동 검토",
  "Over-cap users wait for an administrator decision": "한도를 넘은 사용자는 관리자 결정을 기다립니다",
  "Automatic suspension": "자동 정지",
  "Over-cap users are suspended by every enforcement run": "한도를 넘은 사용자는 집행 실행마다 정지됩니다",
