  "Enforcement": "집행",
  "Automatic: users over their cap are suspended by each enforcement run and restored when the settlement period resets.": "자동: 한도를 넘은 사용자는 집행 실행 때마다 정지되고, 정산 기간이 초기화되면 복원됩니다.",
  "Manual: users over their cap wait in the review queue. An administrator suspends them until the period resets or allows them for the rest of the period.": "수동: 한도를 넘은 사용자는 검토 대기열에 올라갑니다. 관리자가 기간 초기화까지 정지하거나 남은 기간 동안 허용합니다.",
  "Next reset": "다음 초기화",
  "No fixed reset": "고정 초기화 없음",
  "Suspended users are restored when their usage falls below the cap": "정지된 사용자는 사용량이 한도 아래로 내려가면 복원됩니다",
  "Last run": "마지막 실행",
  "Not run yet": "아직 실행 안 됨",
  "Select Run enforcement now or configure the scheduler": "'지금 집행 실행'을 누르거나 스케줄러를 구성하십시오",
  "Scheduler": "스케줄러",
  "Configured": "구성됨",
  "Turn on automatic suspension": "자동 정지 켜기",
  "Switch to manual review": "수동 검토로 전환",
  "Every enforcement run will suspend users over their cap until the settlement period resets. Exception rules and safety gates still apply.": "집행 실행마다 한도를 넘은 사용자를 정산 기간이 초기화될 때까지 정지합니다. 예외 규칙과 안전 게이트는 그대로 적용됩니다.",
  "Enforcement runs will no longer suspend anyone. Users over their cap wait in the review queue for an administrator decision. Suspensions still end when the period resets.": "집행 실행이 더 이상 사용자를 정지하지 않습니다. 한도를 넘은 사용자는 검토 대기열에서 관리자 결정을 기다립니다. 기존 정지는 기간이 초기화되면 끝납니다.",
  "Turn on": "켜기",
  "Switch": "전환",
  "Automatic suspension is on": "자동 정지가 켜졌습니다",
  "Manual review is on": "수동 검토로 전환했습니다",
  "IAM bindings are changed in one atomic update: users over their cap are suspended until the settlement period resets, suspensions whose period ended are restored and exception rules are applied. Users that are not enforceable are never modified.": "IAM 바인딩을 한 번의 원자적 업데이트로 변경합니다. 한도를 넘은 사용자는 정산 기간이 초기화될 때까지 정지되고, 기간이 끝난 정지는 복원되며, 예외 규칙이 적용됩니다. 적용 불가 사용자는 절대 변경하지 않습니다.",
  "Manual review mode: nobody is suspended by this run. Suspensions whose period ended are restored and exception rules are applied; users over their cap stay in the review queue.": "수동 검토 모드: 이번 실행으로 정지되는 사용자는 없습니다. 기간이 끝난 정지는 복원되고 예외 규칙이 적용되며, 한도를 넘은 사용자는 검토 대기열에 남습니다.",
  "Run now": "지금 실행",
  "Suspend": "정지",
  "Block (rule)": "차단(규칙)",
  "No IAM change is needed. Users over their cap are waiting in the review queue.": "IAM 변경이 필요하지 않습니다. 한도를 넘은 사용자는 검토 대기열에 있습니다.",
  "The review queue is computed only when both the IAM policy and the usage telemetry can be read.": "검토 대기열은 IAM 정책과 사용량 텔레메트리를 모두 읽을 수 있을 때만 계산됩니다.",
  "No users awaiting review": "검토를 기다리는 사용자가 없습니다",
  "No suspensions planned": "예정된 정지가 없습니다",
  "No enforceable user is over the cap in this period.": "이번 기간에 한도를 넘은 적용 가능 사용자가 없습니다.",
  "Cap reached": "초과 한도",
