  "Suspended at the next run": "다음 실행에서 정지될 사용자",
  "Users over their cap in this period. A suspension ends automatically when the settlement period resets.": "이번 기간에 한도를 넘은 사용자입니다. 정지는 정산 기간이 초기화되면 자동으로 끝납니다.",
  "Automatic mode: these users are over their cap and will be suspended by the next enforcement run.": "자동 모드: 이 사용자들은 한도를 넘어 다음 집행 실행에서 정지됩니다.",
