  "Allow {email} for this period": "{email} 이번 기간 허용",
  "Antigravity access is removed now (cap marker role) and restored automatically when the settlement period resets.": "지금 Antigravity 접근을 제거하고(한도 마커 역할), 정산 기간이 초기화되면 자동으로 복원합니다.",
  "The user keeps Antigravity access until the settlement period ends, even above the cap. A suspended user is restored now.": "정산 기간이 끝날 때까지 한도를 넘어도 Antigravity 접근을 유지합니다. 정지된 사용자는 지금 복원됩니다.",
