  "Add a rule to always allow a user, always block a user, or give a user an individual cap. Rules apply in both enforcement modes.": "특정 사용자를 항상 허용하거나, 항상 차단하거나, 개별 한도를 주는 규칙을 추가하십시오. 규칙은 두 집행 모드 모두에 적용됩니다.",
