  "The access role will be replaced with the administrative block marker for {email}, and an always-block exception rule is recorded. Enforcement runs will not re-enable this user until the rule is removed.": "{email}의 접근 역할을 관리자 차단 마커로 바꾸고 '항상 차단' 예외 규칙을 기록합니다. 규칙을 삭제할 때까지 집행 실행이 이 사용자를 다시 허용하지 않습니다.",
  "{email} gets Antigravity access back now and keeps it for the rest of the settlement period, even above the cap. An allowed-this-period exception rule is recorded.": "{email}의 Antigravity 접근을 지금 복원하고 남은 정산 기간 동안 한도를 넘어도 유지합니다. '이번 기간 허용' 예외 규칙을 기록합니다.",
  "Restore Antigravity access": "Antigravity 접근 복원",
  "Automatic suspends users over their cap until the period resets; manual waits for an administrator decision.": "자동은 한도를 넘은 사용자를 기간 초기화까지 정지하고, 수동은 관리자 결정을 기다립니다.",
