  "Prices are found automatically: what your billing account actually paid per token in the last 30 days, and the public Google Cloud price list for models without billed usage. Amounts are converted with the Google exchange rate.": "단가는 자동으로 찾습니다. 최근 30일 동안 결제 계정이 실제로 낸 토큰당 단가를 쓰고, 청구 내역이 없는 모델은 Google Cloud 공개 가격표를 씁니다. 금액은 Google 환율로 환산합니다.",
  "Automatic (recommended)": "자동 (권장)",
