  "Caps apply to each person within the settlement period. Give specific people a different amount from the Cost cap column of the usage table or with exception rules.": "한도는 정산 기간 동안 1인별로 적용됩니다. 특정 사용자에게 다른 금액을 주려면 사용량 표의 비용 한도 열이나 예외 규칙을 사용하십시오.",
  "Users above this estimated cost are suspended (automatic mode) or queued for review.": "추정 비용이 이 금액을 넘으면 정지(자동 모드)되거나 검토 대기열에 올라갑니다.",
