  "Grouping rules: 1) Primary host project, 2) Explicitly linked projects below, 3) Active projects auto-discovered via Cloud Resource Manager (excluding auth bridge projects). Grant cross-project read IAM via scripts/deploy.sh --project {id} --link-projects projA,projB.": "그룹화 규칙: 1) 기본 호스트 프로젝트, 2) 아래에 명시적으로 연동한 프로젝트, 3) Cloud Resource Manager를 통해 자동 탐색된 활성 프로젝트(인증 브리지 프로젝트 제외). 교차 프로젝트 읽기 권한은 scripts/deploy.sh --project {id} --link-projects projA,projB 명령으로 일괄 부여할 수 있습니다.",
