  "BigQuery Billing Export is not configured. Spend is calculated from observed token usage ({tokens} tokens) multiplied by official Google per-1M-token rates ({fx}).": "BigQuery 결제 내보내기(Billing Export)가 연결되어 있지 않아, 관측된 토큰 사용량({tokens} 토큰)에 Google 공식 1M 토큰당 단가({fx})를 곱해 비용을 자동 역산하고 있습니다.",
  "{n} models have token usage without an official price": "공식 단가가 없는 모델 {n}종에서 토큰 사용량이 감지되었습니다",
  "Tokens of unpriced models are excluded from cost estimates until an alias or administrator price is set in Settings > Data collection and cost.": "단가가 없는 모델의 토큰은 설정 > 데이터 수집 및 비용에서 모델 별칭이나 관리자 지정 단가를 등록하기 전까지 추정 비용에서 제외됩니다.",
