  "Priority 1: BigQuery Billing Export when configured. Priority 2 (active): reverse cost estimation from observed tokens multiplied by official Google token prices and synced exchange rates.": "우선순위 1: BigQuery 결제 내보내기 연결 시 실제 청구 비용을 표시합니다. 우선순위 2(현재 활성): 관측된 토큰 사용량에 Google 공식 토큰 단가와 동기화 환율을 곱해 역산 추정합니다.",
