  "Fallback models": "대체(폴백) 모델",
  "Comma separated model IDs tried in order when a requested model is not available in this project, for example a preview model.": "요청한 모델(예: 프리뷰 모델)을 이 프로젝트에서 사용할 수 없을 때 순서대로 시도할 모델 ID 목록입니다(쉼표로 구분).",
