  "\"{value}\" is not an https address on *.google.com or *.google.dev.": "\"{value}\"은(는) *.google.com 또는 *.google.dev 도메인의 https 주소가 아닙니다.",
  "\"{value}\" is not valid here.": "\"{value}\"은(는) 여기에 사용할 수 없는 값입니다.",
