  "Prices and exchange rates": "공식 단가 및 환율",
  "Official token prices and exchange rates for cost estimates when the billing export cannot be read. Nothing is built in: prices come from the sources below.": "결제 내보내기를 읽을 수 없을 때 토큰 사용량 기반 비용 역산에 사용할 공식 단가와 환율 설정입니다. 고정된 내장 단가 없이 아래 출처에서 매일 가져옵니다.",
