  "High volume: live Logging dashboards read at most {n} entries per view. Route to BigQuery with cost controls for complete history.": "고볼륨 로그: 실시간 Logging 대시보드는 화면당 최대 {n}건까지만 읽습니다. 전체 집계와 장기 보관이 필요하면 비용 제어를 걸어 BigQuery로 적재하십시오.",
