  "New logs appear automatically after a service writes to Cloud Logging. Adjust discovery windows, field hints and Gemini profiling under Settings > Data collection and cost.": "서비스가 Cloud Logging에 로그를 남기면 여기에 자동으로 나타납니다. 탐색 범위, 필드 힌트, Gemini 분석 설정은 설정 > 데이터 수집 및 비용에서 조정할 수 있습니다.",
  "Live Cloud Logging dashboards cover Cloud Logging retention and read up to {n} entries per view (configurable in Settings). For full history and SQL aggregation without runaway spend, create a cost-controlled BigQuery route.": "실시간 Cloud Logging 대시보드는 기본 보관 기간 내에서 조회당 최대 {n}건(설정에서 변경 가능)을 읽습니다. 과도한 비용 없이 전체 이력과 SQL 집계를 사용하려면 비용 제어형 BigQuery 적재 라우트를 생성하십시오.",
