  "Select at least one log or enter a Cloud Logging filter.": "적재할 로그를 하나 이상 선택하거나 Cloud Logging 필터를 입력하십시오.",
  "Sample rate must be between 0.01 and 100.": "샘플링 비율은 0.01에서 100 사이여야 합니다.",
  "Daily budget cap must be 0 or greater.": "일일 용량 상한은 0 이상이어야 합니다.",
  "Retention days must be a whole number from 0 to 3650.": "보관 기간은 0에서 3650 사이의 정수여야 합니다.",
  "BigQuery route updated": "BigQuery 적재 라우트가 업데이트되었습니다",
  "BigQuery route created": "BigQuery 적재 라우트가 생성되었습니다",
  "This log has more entries in the selected period than a dashboard reads from Cloud Logging. Counts start at {time}; earlier days have no bars. Route the log to BigQuery for complete counts.": "선택한 기간의 로그 수가 실시간 Cloud Logging 대시보드 조회 한도를 초과했습니다. 집계는 {time}부터 시작되며 이전 날짜 막대는 비어 있습니다. 전체 집계가 필요하면 BigQuery로 적재하십시오.",
  "{product} · {log}": "{product} · {log}",
  "{log}": "{log}",
  "{name}": "{name}",
  "{name} · {resource}": "{name} · {resource}",
  "Log entries that {product} writes to Cloud Logging under {log}, from {resources}.": "{product}이(가) {resources} 리소스에서 Cloud Logging에 {log} 이름으로 기록하는 로그입니다.",
  "Log entries written to Cloud Logging under the name {log}, from {resources}.": "{resources} 리소스에서 Cloud Logging에 {log} 이름으로 기록된 로그입니다.",
  "Log entries of {product} exported from Cloud Logging to the BigQuery dataset {dataset}.": "{product} 로그를 Cloud Logging에서 BigQuery 데이터셋 {dataset}(으)로 내보낸 테이블입니다.",
  "Structured JSON entries that the workload {name} ({resource}) writes to {logs}.": "워크로드 {name}({resource})이(가) {logs}에 기록하는 구조화된 JSON 로그입니다.",
  "Source log": "원본 로그",
  "No exchange rate for USD/{a} is available yet, so estimates are shown in USD.": "아직 USD/{a} 환율 정보가 없어 추정 비용을 USD로 표시합니다.",
  "{a} model(s) have no official price yet ({b}); their tokens are counted at zero cost. Add an alias or a price in Settings > Data collection and cost.": "아직 공식 단가가 없는 모델 {a}종({b})의 토큰은 0원으로 집계되었습니다. 설정 > 데이터 수집 및 비용에서 모델 별칭이나 관리자 단가를 추가하십시오.",
  "Only the first {a} log names per project are listed.": "프로젝트당 처음 {a}개의 로그 이름만 표시합니다.",
  "The maximum number of routes ({a}) has been reached.": "생성 가능한 최대 라우트 수({a}개)에 도달했습니다.",
  "A route can send at most {a} logs.": "한 라우트에는 최대 {a}개의 로그까지만 포함할 수 있습니다.",
  "Daily budget exceeded ({a} GiB / {b} GiB)": "일일 용량 상한 초과 ({a} GiB / {b} GiB)",
  "Workspace daily budget exceeded ({a} GiB / {b} GiB)": "워크스페이스 일일 총예산 초과 ({a} GiB / {b} GiB)",
  "The routing dataset name in Settings is invalid.": "설정에 지정된 적재 데이터셋 이름이 올바르지 않습니다.",
  "The route filter is empty or too long; route fewer logs per route.": "라우트 필터가 비어 있거나 너무 깁니다. 라우트당 포함할 로그 수를 줄이십시오.",
  "Each routed log must be a full log name (projects/<id>/logs/<log id>).": "적재할 로그는 전체 로그 이름(projects/<id>/logs/<log id>) 형식이어야 합니다.",
  "All logs of one route must belong to the route's project.": "하나의 라우트에 포함되는 로그는 모두 같은 프로젝트 소속이어야 합니다.",
  "Route not found.": "라우트를 찾을 수 없습니다.",
  "Field 'project' must be a project of this workspace.": "'project'는 이 워크스페이스에 연동된 프로젝트여야 합니다.",
  "Select at least one log or enter a filter.": "로그를 하나 이상 선택하거나 필터를 입력하십시오.",
  "The sink name may contain only letters, digits, '_' and '-'.": "싱크 이름에는 영문자, 숫자, '_', '-'만 사용할 수 있습니다.",
  "Specify 'id' or 'all': true to acknowledge pricing alerts.": "단가 알림을 확인 처리하려면 'id' 또는 'all': true를 지정하십시오.",
  "The group dashboard could not be created.": "그룹 대시보드를 생성할 수 없습니다.",
  "Non-token media units (video seconds, audio clips, speech minutes) and VM/storage infrastructure require BigQuery Billing Export for actual usage totals.": "토큰 외 과금 항목(동영상 초, 오디오 클립, 음성 인식 분 단위) 및 VM·스토리지 인프라 실사용 비용은 BigQuery 결제 내보내기 연결 시 집계됩니다.",
  "Media & speech unit rates": "미디어·음성 비토큰 단가",
  "Catalog list prices": "카탈로그 공시 단가",
  "Official media & speech unit prices (non-token SKUs)": "공식 미디어·음성 단위 단가 (비토큰 SKU)",
  "Synced from Cloud Billing Catalog API for video, music, image, Text-to-Speech character and Speech-to-Text minute SKUs. Actual billed quantities require BigQuery Billing Export.": "동영상(Veo), 음악(Lyria), 이미지(Imagen), 음성 합성(문자당), 음성 인식(분당) SKU의 Cloud Billing 카탈로그 공시 단가입니다. 실제 청구 수량 집계에는 BigQuery 결제 내보내기가 필요합니다.",
  "Billing unit": "과금 단위",
  "List price (USD)": "공시 단가 (USD)",
  "List price ({currency})": "공시 단가 ({currency})",
  "Video": "동영상",
  "Audio / Music": "오디오·음악",
  "Text-to-Speech": "음성 합성 (TTS)",
  "Speech-to-Text": "음성 인식 (STT)",
  "Resets every day at {time} ({tz})": "매일 {time}에 초기화 ({tz})",
  "Resets every {day} at {time} ({tz})": "매주 {day} {time}에 초기화 ({tz})",
  "Resets on the 1st of every month at {time} ({tz})": "매월 1일 {time}에 초기화 ({tz})",
  "Monday": "월요일",
  "Tuesday": "화요일",
  "Wednesday": "수요일",
