  "Open the agent details for its telemetry, models and tools, traces, topology, revisions, evaluation and playground.": "에이전트 상세에서 텔레메트리, 모델 및 도구, 트레이스, 토폴로지, 리비전, 평가, 플레이그라운드를 볼 수 있습니다.",
  "No agent-reported metrics in this period": "이 기간에 에이전트가 보고한 지표가 없습니다",
  "Invocation, model, tool and token metrics appear when the agent is built with Agent Development Kit 2.6 or later and deployed with GOOGLE_CLOUD_AGENT_ENGINE_ENABLE_TELEMETRY=true.": "호출·모델·도구·토큰 지표는 에이전트를 Agent Development Kit 2.6 이상으로 만들고 GOOGLE_CLOUD_AGENT_ENGINE_ENABLE_TELEMETRY=true로 배포하면 표시됩니다.",
  "Agent telemetry is turned off for this deployment": "이 배포는 에이전트 텔레메트리가 꺼져 있습니다",
  "GOOGLE_CLOUD_AGENT_ENGINE_ENABLE_TELEMETRY is set to false, so the agent sends no traces and no agent-reported metrics. Runtime metrics below are still collected.": "GOOGLE_CLOUD_AGENT_ENGINE_ENABLE_TELEMETRY가 false로 설정되어 있어 에이전트가 트레이스와 자체 보고 지표를 보내지 않습니다. 아래 런타임 지표는 계속 수집됩니다.",
  "Requests that reached the agent runtime, from the Cloud Monitoring metric request_count.": "에이전트 런타임에 도달한 요청 수입니다. Cloud Monitoring 지표 request_count 기준입니다.",
