  "Answer cut at the size or time limit": "크기 또는 시간 한도에서 응답이 잘렸습니다",
  "The playground is available to administrators": "플레이그라운드는 관리자만 사용할 수 있습니다",
  "Sending a message runs the deployed agent, including its model and tool calls, so the playground is limited to administrators.": "메시지를 보내면 배포된 에이전트가 모델 호출과 도구 호출을 포함해 실제로 실행되므로 플레이그라운드는 관리자에게만 열려 있습니다.",
  "The playground cannot call this agent": "플레이그라운드에서 이 에이전트를 호출할 수 없습니다",
  "The playground talks to agents that expose a streaming query method (agents built with the Agent Development Kit). This deployment does not expose one.": "플레이그라운드는 스트리밍 쿼리 메서드를 제공하는 에이전트(Agent Development Kit로 만든 에이전트)와 대화합니다. 이 배포에는 해당 메서드가 없습니다.",
  "Messages run the deployed agent": "메시지를 보내면 배포된 에이전트가 실행됩니다",
  "Each message calls the live deployment with your account as the user ID. The agent can call its models and tools, which costs tokens and can change data in the systems it is connected to. Every call is written to the governance audit log without the message text.": "메시지마다 내 계정을 사용자 ID로 하여 실제 배포를 호출합니다. 에이전트가 모델과 도구를 호출하므로 토큰 비용이 발생하고, 연결된 시스템의 데이터가 바뀔 수 있습니다. 모든 호출은 메시지 본문 없이 거버넌스 감사 로그에 기록됩니다.",
  "Conversation with the agent": "에이전트와의 대화",
  "New session": "새 세션",
  "Message to the agent": "에이전트에 보낼 메시지",
  "Try the agent": "에이전트 사용해 보기",
  "Send a message to see how the deployed agent answers, which tools it calls and what they return.": "메시지를 보내 배포된 에이전트가 어떻게 답하는지, 어떤 도구를 호출하고 무엇을 돌려받는지 확인하십시오.",
  "Only the first {a} runtime revisions are listed.": "처음 {a}개의 런타임 리비전만 표시합니다.",
  "Field 'message' must be 1 to {a} characters.": "메시지는 1~{a}자여야 합니다.",
