  "Low": "낮음",
  "No authorization policy: all outbound traffic is blocked": "인가 정책 없음: 모든 아웃바운드 트래픽 차단됨",
  "An Agent-to-Anywhere gateway without an authorization policy denies every request. Set up access authorization so that agents can reach the destinations they are allowed to use.": "인가 정책이 없는 Agent-to-Anywhere 게이트웨이는 모든 요청을 거부합니다. 에이전트가 허용된 대상에 도달할 수 있도록 액세스 인가를 설정하십시오.",
  "No access authorization": "액세스 인가 미구성",
  "Requests are not checked against IAM access policies, so an agent bound to this gateway can reach any destination that the content policies let through.": "요청을 IAM 액세스 정책과 대조하지 않으므로, 이 게이트웨이에 연결된 에이전트는 콘텐츠 정책을 통과하는 모든 대상에 도달할 수 있습니다.",
  "Access authorization is audit-only": "액세스 인가가 감사 전용 모드임",
  "Identity-Aware Proxy evaluates and logs every request but does not block the ones it would deny. Review them in the Traffic view, then enforce the policies.": "Identity-Aware Proxy가 모든 요청을 평가하고 기록하지만 거부 대상 요청을 실제로 차단하지는 않습니다. 트래픽 화면에서 내역을 확인한 뒤 정책을 적용하십시오.",
  "Legacy allow policies (V1)": "레거시 허용 정책(V1)",
  "Unified Access Policies (V2) are recommended for fine-grained access control.": "세분화된 액세스 제어를 위해 통합 액세스 정책(V2) 사용을 권장합니다.",
  "An authorization extension fails open": "인가 확장 프로그램이 Fail-Open으로 설정됨",
  "When the extension fails or times out, requests continue without that check.": "확장 프로그램에 오류가 발생하거나 시간이 초과되면 해당 검사 없이 요청이 통과됩니다.",
  "No content security": "콘텐츠 보안 미구성",
  "Prompts and tool responses that pass through this gateway are not screened by Model Armor.": "이 게이트웨이를 통과하는 프롬프트와 도구 응답을 Model Armor로 검사하지 않습니다.",
  "Inbound requests are not screened": "인바운드 요청 미검사",
  "A Client-to-Agent gateway without a content policy passes every request through. Attach a Model Armor policy to screen prompts.": "콘텐츠 정책이 없는 Client-to-Agent 게이트웨이는 모든 요청을 그대로 통과시킵니다. 프롬프트를 검사하려면 Model Armor 정책을 연결하십시오.",
  "Semantic governance is in dry run": "시맨틱 거버넌스가 시범 실행(Dry Run) 모드임",
  "Verdicts are logged, but tool calls that violate a policy are not blocked.": "판정 결과는 기록되지만 정책을 위반한 도구 호출을 차단하지는 않습니다.",
  "No Agent Registry associated": "연결된 Agent Registry 없음",
  "Destinations cannot be matched to registered agents, MCP servers or endpoints, so only policies for unregistered endpoints can allow traffic.": "대상을 등록된 에이전트, MCP 서버 또는 엔드포인트와 매칭할 수 없어 미등록 엔드포인트용 정책으로만 트래픽을 허용할 수 있습니다.",
  "Agent Registry does not match the gateway": "Agent Registry가 게이트웨이와 일치하지 않음",
  "A gateway uses the regional Agent Registry of its own project and region.": "게이트웨이는 동일한 프로젝트 및 리전의 리전별 Agent Registry를 사용합니다.",
  "Request logging is turned off": "요청 로깅이 꺼져 있음",
