  "The policy enforcement point for agent traffic: which gateways exist, how they are governed, what they allowed and denied, and which agents bypass them.": "에이전트 트래픽의 정책 집행 지점입니다. 구성된 게이트웨이와 거버넌스 상태, 허용·거부된 트래픽, 게이트웨이를 우회하는 에이전트를 확인하고 관리합니다.",
