  "AI service and dashboard access for {email} has been revoked by an administrator. Contact your administrator or choose another account.": "관리자가 {email} 계정의 AI 서비스 및 대시보드 접근 권한을 회수했습니다. 관리자에게 문의하거나 다른 계정으로 로그인하세요.",
  "AI service and dashboard access for this account has been revoked by an administrator. Contact your administrator or choose another account.": "관리자가 이 계정의 AI 서비스 및 대시보드 접근 권한을 회수했습니다. 관리자에게 문의하거나 다른 계정으로 로그인하세요.",
  "Access to this workspace has been blocked by an administrator.": "관리자에 의해 이 워크스페이스 접근이 차단되었습니다.",
