  "Only Antigravity (businessaicode.*) is blocked; Gemini Enterprise web access remains enabled.": "Antigravity 코딩 에이전트(businessaicode.*)만 차단된 상태이며, Gemini Enterprise 웹 접속은 유지됩니다.",
