  "Stops or restores Antigravity coding IDE permissions (businessaicode.*) while keeping Gemini Enterprise web chat enabled.": "Gemini Enterprise 웹 채팅은 유지한 채 Antigravity 코딩 에이전트 권한(businessaicode.*)만 차단하거나 복원합니다.",
  "Overall status": "전체 상태",
