  "Direct AI IAM roles still present": "직접 부여된 AI IAM 역할이 남아 있습니다",
  "The following AI roles still exist on this user in Google Cloud IAM: {roles}. Select Block all AI access to remove them.": "Google Cloud IAM에 아직 다음 AI 역할이 남아 있습니다: {roles}. '전체 AI 접근 차단'을 눌러 제거하세요.",
  "Every direct AI IAM role (Gemini Enterprise, NotebookLM, Antigravity, Agent Platform and marker roles) on this project will be removed for {email}, active dashboard sessions will end immediately, and future dashboard sign-ins will be blocked until restored.": "{email} 계정에 직접 부여된 이 프로젝트의 모든 AI IAM 역할(Gemini Enterprise, NotebookLM, Antigravity, Agent Platform, 마커 역할)을 즉시 제거하고, 현재 로그인된 대시보드 세션을 종료하며, 차단 해제 전까지 대시보드 로그인도 막습니다.",
  "Dashboard sign-in and project AI IAM roles ({roles}) will be restored for {email}.": "{email} 계정의 대시보드 로그인과 프로젝트 AI IAM 역할({roles})을 복원합니다.",
  "Dashboard sign-in and the default Gemini Enterprise access role will be restored for {email}.": "{email} 계정의 대시보드 로그인과 기본 Gemini Enterprise 접근 역할을 복원합니다.",
