  "AI access restored": "전체 AI 접근 복원 완료",
  "{email}: restored {roles} and unblocked dashboard sign-in.": "{email}: {roles} 역할을 복원하고 대시보드 로그인 차단을 해제했습니다.",
  "You cannot block your own account.": "본인 계정은 차단할 수 없습니다.",
  "This user is a dashboard administrator. Remove administrator privileges in Settings > Access control first.": "이 사용자는 대시보드 관리자입니다. 먼저 설정 > 접근 제어에서 관리자 권한을 해제하십시오.",
  "This user holds {a} on the project, which grants full project control beyond AI services. Remove that role in Google Cloud IAM first.": "이 사용자는 AI 서비스를 넘어 프로젝트 전체를 제어하는 {a} 역할을 보유하고 있습니다. 먼저 Google Cloud IAM에서 해당 역할을 제거하십시오.",
  "Conditional project IAM bindings remain ({a}) and must be removed in Google Cloud IAM.": "조건부 프로젝트 IAM 바인딩({a})이 남아 있어 Google Cloud IAM에서 직접 제거해야 합니다.",
  "A Google Group or domain IAM binding on an AI role still grants access.": "AI 역할에 Google 그룹 또는 도메인 단위 IAM 바인딩이 있어 여전히 접근 권한이 부여됩니다.",
  "An inherited folder or organization IAM binding still grants access.": "상위 폴더 또는 조직의 상속 IAM 바인딩으로 여전히 접근 권한이 부여됩니다.",
