  "AI usage cost allocated to organization units, people and projects. A month close freezes the figures of a finished month.": "AI 사용 비용을 조직 단위, 사람, 프로젝트별로 배분합니다. 월 마감을 하면 끝난 달의 수치가 확정되어 더 이상 바뀌지 않습니다.",
  "Some amounts are unknown": "일부 금액을 알 수 없음",
  "A model used in this month has no unit price. Amounts that need it are shown as a dash and left out of the totals. Add the price or a model alias in Settings > Data collection and cost.": "이 달에 사용된 모델 중 단가가 없는 모델이 있습니다. 그 단가가 필요한 금액은 —로 표시되며 합계에서 빠집니다. 설정 > 데이터 수집 및 비용에서 단가나 모델 별칭을 추가하십시오.",
  "No organization structure yet": "아직 조직 구조가 없습니다",
  "Import a CSV that maps people and projects to organization units to see costs by unit. Until then, costs are shown by project and person.": "사람과 프로젝트를 조직 단위에 매핑한 CSV를 가져오면 조직 단위별 비용을 볼 수 있습니다. 그 전까지는 프로젝트별, 사람별 비용만 표시됩니다.",
  "Costs are shown by project and person until an administrator imports the organization structure.": "관리자가 조직 구조를 가져오기 전까지는 프로젝트별, 사람별 비용만 표시됩니다.",
  "Import organization CSV": "조직 CSV 가져오기",
