  "CSV columns: principal,unit_path,cost_center, with this header row. One row per person or project; a row with an empty principal only defines a unit.": "CSV 열: principal,unit_path,cost_center (이 헤더 행 필수). 사람 또는 프로젝트마다 한 행씩 작성하며, principal이 비어 있는 행은 조직 단위만 정의합니다.",
  "principal: an e-mail address, user:EMAIL, a workforce identity principal URI or project:PROJECT_ID. unit_path: unit names separated by /, for example Company/Division/Team (up to 10 levels). cost_center is optional.": "principal: 이메일 주소, user:EMAIL, 직원 ID 제휴 주 구성원 URI 또는 project:PROJECT_ID. unit_path: /로 구분한 조직 단위 이름(예: 회사/본부/팀, 최대 10단계). cost_center는 선택 항목입니다.",
  "Save the file as CSV UTF-8, up to 5 MB. Every file is checked first, and applying it replaces the whole structure. Closed months keep the figures they were closed with.": "파일은 CSV UTF-8 형식으로 저장하십시오(최대 5MB). 모든 파일은 먼저 점검하며, 적용하면 조직 구조 전체가 바뀝니다. 마감된 달은 마감 당시의 수치를 유지합니다.",
