  "Usage logs unavailable": "사용 로그를 읽을 수 없음",
  "The CSV file could not be read at row {a}. Check the quotes in that row.": "CSV 파일의 {a}행을 읽을 수 없습니다. 해당 행의 따옴표를 확인하십시오.",
  "The CSV file must be UTF-8 text.": "CSV 파일은 UTF-8 텍스트여야 합니다.",
  "The organization model was changed at the same time. Run the check again.": "조직 구조가 동시에 변경되었습니다. 점검을 다시 실행하십시오.",
