  "License assignments could not be read, so seat costs are missing.": "라이선스 할당 정보를 읽을 수 없어 좌석 비용이 빠져 있습니다.",
  "The month close snapshot could not be read; live figures are shown.": "월 마감 스냅샷을 읽을 수 없어 현재 수치를 표시합니다.",
  "The chargeback close dataset is not a valid identifier.": "비용 정산 마감 데이터 세트 이름이 올바르지 않습니다.",
  "In scope": "범위 내",
  "The user signs in through Workforce Identity Federation (an external identity provider). Usage and cost are counted, but per-user caps cannot act on workforce principals. Restrict access through the identity provider or the workforce pool bindings.": "외부 ID 공급업체(Workforce Identity Federation)로 로그인하는 사용자입니다. 사용량과 금액은 집계되지만 사용자별 한도는 Workforce 주체에 적용할 수 없습니다. ID 공급업체나 Workforce 풀 바인딩으로 액세스를 제한하세요.",
  "The month must look like YYYY-MM.": "월은 YYYY-MM 형식이어야 합니다.",
  "Parameter 'month' must not be in the future.": "미래의 월은 선택할 수 없습니다.",
  "Parameter 'level' must be user, unit or project.": "level 값은 user, unit, project 중 하나여야 합니다.",
  "People over their limits are added to the deny policy at every attachment point until the settlement period resets, people whose suspension ended are removed from it and exception rules are applied. Changes take a few minutes to take effect.": "한도를 넘은 사람은 정산 기간이 초기화될 때까지 모든 부착 지점의 거부 정책에 추가되고, 정지가 끝난 사람은 거부 정책에서 제거되며, 예외 규칙이 적용됩니다. 변경 사항이 반영되기까지 몇 분 걸립니다.",
  "Notify only: no access is changed. The run records and notifies what it would do.": "알림만: 액세스를 바꾸지 않습니다. 실행은 수행할 조치를 기록하고 알리기만 합니다.",
  "The enforcement job applies the changes with its own service account.": "집행 작업이 자체 서비스 계정으로 변경 사항을 적용합니다.",
  "IAM deny policy": "IAM 거부 정책",
  "Notify only": "알림만",
  "Allow policy swap": "허용 정책 교체",
  "Suspended people are listed in a deny policy, which also stops access through groups and inherited roles.": "정지된 사람을 거부 정책에 등록합니다. 그룹이나 상속된 역할로 받은 액세스도 막습니다.",
  "Runs plan and notify only; nobody loses access.": "실행은 계획과 알림만 하며, 누구의 액세스도 막지 않습니다.",
  "The direct role binding is swapped for a marker role in the primary project.": "기본 프로젝트에서 직접 역할 바인딩을 마커 역할로 교체합니다.",
  "The folders or organization of the workspace scope": "워크스페이스 범위의 폴더 또는 조직",
