  "{email} is over the cap now ({usage}). Enforcement runs right away to suspend {email} until usage falls below the cap.": "{email}은(는) 현재 한도를 초과했습니다({usage}). 즉시 집행을 실행해 사용량이 한도 아래로 내려갈 때까지 정지합니다.",
  "Enforcement job started to apply the change. The status updates in about a minute.": "변경 사항을 반영하기 위해 집행 작업을 즉시 시작했습니다. 약 1분 뒤 상태가 업데이트됩니다.",
