  "Schedule only. Redeploy with REALTIME_ENFORCEMENT=true to trigger enforcement as soon as usage logs arrive.": "예약 집행만 사용 중입니다. 사용 로그 수신 즉시 집행하려면 REALTIME_ENFORCEMENT=true로 다시 배포하세요.",
  "Last usage event {when}": "마지막 사용 이벤트 {when}",
