  "Users already over their cap are evaluated right away, and every enforcement run suspends over-cap users until the settlement period resets. Exception rules and safety gates still apply.": "이미 한도를 초과한 사용자는 즉시 평가되며, 이후 매 집행 실행마다 한도 초과 사용자를 기간 초기화 때까지 정지합니다. 예외 규칙과 안전 게이트는 그대로 적용됩니다.",
  "Schedule only": "예약 집행만",
  "Real-time detection": "실시간 감지",
  "Automatic mode (real-time): enforcement runs as soon as a usage log exceeds the cap; IAM changes take a few minutes to take effect.": "자동 모드(실시간): 한도를 넘는 사용 로그가 들어오면 즉시 집행을 시작합니다. IAM 정책 반영에는 수 분이 걸릴 수 있습니다.",
