  "Caps apply to each person within the configured cap period. Give specific people a different amount from the Cost cap column of the usage table or with exception rules.": "설정한 정산 기간 동안 사용자별로 한도가 적용됩니다. 특정 사용자에게 다른 한도를 주려면 사용량 표의 비용 한도 열이나 예외 규칙을 사용하세요.",
